@staticmethod

def generate_from_log(
    self,
    repo_path: str,
    from_ref: str,
    to_ref: str = "HEAD",
) -> str:
    entries = self._collect_entries(repo_path, from_ref, to_ref)
    return self._format_entries(entries)

def generate_from_messages(self, messages: list[str]) -> str:
    entries = []
    for msg in messages:
        try:
            parsed = CommitMessage.parse(msg)
            entries.append(
                ChangelogEntry(
                    commit_type=parsed.commit_type,
                    message=msg,
                )
            )
        except ValueError:
            entries.append(
                ChangelogEntry(
                    commit_type=CommitType.CHORE,
                    message=msg,
                )
            )
    return self._format_entries(entries)

def _collect_entries(self, repo_path: str, from_ref: str, to_ref: str) -> list[ChangelogEntry]:
    entries = []
    try:
        result = subprocess.run(
            ["git", "-C", repo_path, "log", f"{from_ref}..{to_ref}",
             "--pretty=format:%s|||%an|||%h"],
            capture_output=True, text=True, check=False,
        )
        if result.returncode == 0 and result.stdout.strip():
            for line in result.stdout.strip().split("\n"):
                parts = line.split("|||")
                msg = parts[0] if len(parts) > 0 else ""
                author = parts[1] if len(parts) > 1 else ""
                sha = parts[2] if len(parts) > 2 else ""
                if msg:
                    entry = ChangelogEntry.from_git_log_line(msg, author, sha)
                    entries.append(entry)
    except (subprocess.SubprocessError, FileNotFoundError):
        pass
    return entries

def _format_entries(self, entries: list[ChangelogEntry]) -> str:
    if not entries:
        return f"{self._config.changelog_header}\n\nNo changes recorded.\n"

    sections: dict[str, list[ChangelogEntry]] = defaultdict(list)
    for entry in entries:
        header = entry.commit_type.section_header()
        sections[header].append(entry)

    header_order = [
        "Features", "Bug Fixes", "Hotfixes", "Code Refactoring",
        "Documentation", "Style Changes", "Chores", "Tests",
        "Releases", "Patches",
    ]

    lines = [self._config.changelog_header, ""]
    for section_name in header_order:
        section_entries = sections.get(section_name, [])
        if not section_entries:
            continue
        lines.append(f"### {section_name}")
        lines.append("")
        for entry in section_entries:
            sha_suffix = f" ({entry.sha})" if entry.sha else ""
            author_suffix = f" by {entry.author}" if entry.author else ""
            lines.append(f"  * {entry.message}{sha_suffix}{author_suffix}")
        lines.append("")

    lines.append(f"\n_Generated by [deploynator]({self._config.deploynator_badge_url})_")
    return "\n".join(lines)

def create(overrides: dict | None = None) -> Config:
    base = Config()
    if not overrides:
        return base
    return Config(**{**{f.name: getattr(base, f.name) for f in Config.__dataclass_fields__.values()}, **overrides})

def resolve_path(self, *parts: str) -> str:
    if self._path:
        return os.path.join(self._path, *parts)
    return os.path.join(*parts)

@property

def gh_authd(self) -> bool:
    return os.environ.get(self.github_token_env) is not None

@property

def glab_authd(self) -> bool:
    return os.environ.get(self.gitlab_token_env) is not None

@property

def discover(self, search_path: str = "") -> list[ProjectConfig]:
    base = search_path or self._config._path or os.getcwd()
    projects_dir = os.path.join(base, self._config.projects_dir)

    if not os.path.isdir(projects_dir):
        project_yaml = os.path.join(base, "deploynator.yaml")
        if os.path.isfile(project_yaml):
            return [self._load_single(project_yaml)]
        return []

    projects = []
    for entry in sorted(os.listdir(projects_dir)):
        if entry.endswith((".yaml", ".yml")):
            yaml_path = os.path.join(projects_dir, entry)
            try:
                project = self._load_single(yaml_path)
                projects.append(project)
            except (ValueError, KeyError, OSError):
                continue
    return projects

def find_by_name(self, name: str, search_path: str = "") -> ProjectConfig | None:
    for project in self.discover(search_path):
        if project.name == name:
            return project
    return None

@staticmethod

def _load_single(yaml_path: str) -> ProjectConfig:
    import yaml
    if os.path.islink(yaml_path):
        raise ValueError(f"Symlink rejected: {yaml_path}")
    if os.path.getsize(yaml_path) > Config.create().max_file_size_bytes:
        raise ValueError(f"File too large: {yaml_path}")
    with open(yaml_path, "r") as f:
        data = yaml.safe_load(f)
    if not data or "name" not in data:
        raise ValueError(f"Invalid project config: {yaml_path}")
    return ProjectConfig.from_dict(data)

def _resolve_project_path(project: ProjectConfig) -> str:
    if not project.path:
        return os.getcwd()
    if os.path.isabs(project.path):
        return project.path
    base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    resolved = os.path.join(base, project.path)
    return os.path.abspath(resolved)

def _listed(files: list) -> str:
    shown = [f"- {f}" for f in files[:_MAX_LISTED]]
    if len(files) > _MAX_LISTED:
        shown.append(f"- ... and {len(files) - _MAX_LISTED} more")
    return "\n".join(shown)

