def _add_temp_remote(self, repo_path: str, name: str, url: str) -> None:
    try:
        subprocess.run(
            ["git", "-C", repo_path, "remote", "add", name, url],
            capture_output=True, text=True, check=False,
        )
    except FileNotFoundError:
        pass

