def install_lazygit(self) -> bool:
    try:
        result = subprocess.run(
            ["which", "lazygit"],
            capture_output=True, text=True, check=False,
        )
        if result.returncode == 0:
            return True
        install_methods = [
            ["brew", "install", "lazygit"],
            ["npm", "install", "-g", "lazygit"],
        ]
        for method in install_methods:
            try:
                result = subprocess.run(method, capture_output=True, text=True, check=False)
                if result.returncode == 0:
                    return True
            except FileNotFoundError:
                continue
    except FileNotFoundError:
        pass
    return False

def run(self, project_path: str, toml: TomlConfig) -> bool:
    if not toml.docs_auto:
        return True
    cmd_str = (toml.docs_command or "").strip()
    if not cmd_str:
        print("[!] docs command empty, skipping")
        return True
    try:
        argv = shlex.split(cmd_str)
    except ValueError as exc:
        print(f"[!] invalid docs command: {exc}")
        return False
    if not argv:
        return True
    try:
        result = subprocess.run(
            argv,
            cwd=project_path,
            capture_output=True,
            text=True,
            check=False,
            shell=False,
            timeout=toml.docs_timeout_s,
        )
    except FileNotFoundError:
        print("[!] readmenator not available. Install: pip install readmenator")
        return False
    except subprocess.TimeoutExpired:
        print(f"[!] docs timed out after {toml.docs_timeout_s}s, continuing")
        return False
    if result.returncode != 0:
        err = (result.stderr or result.stdout or "").strip()[:500]
        print(f"[!] docs failed ({cmd_str}), continuing: {err}")
        return False
    print("[+] docs regenerated via readmenator")
    return True

def check_gpg(self) -> tuple[bool, str]:
    try:
        key_id = subprocess.run(
            ["git", "config", "--get", "user.signingkey"],
            capture_output=True, text=True, check=False,
        )
        if key_id.returncode != 0 or not key_id.stdout.strip():
            return False, "GPG signing key not configured"
        gpg_check = subprocess.run(
            ["gpg", "--list-secret-keys", key_id.stdout.strip()],
            capture_output=True, text=True, check=False,
        )
        if gpg_check.returncode == 0:
            return True, key_id.stdout.strip()
        return False, "Secret key not found"
    except FileNotFoundError:
        return False, "gpg or git not found"

def gpg_sign_flag(self) -> list[str]:
    ok, _ = self.check_gpg()
    return ["-S"] if ok else []

def clone(self, url: str, dest: str, depth: int = 1) -> bool:
    try:
        result = subprocess.run(
            ["git", "clone", "--depth", str(depth), url, dest],
            capture_output=True, text=True, check=False,
        )
        return result.returncode == 0
    except FileNotFoundError:
        return False

def add_all(self, repo_path: str) -> bool:
    try:
        result = subprocess.run(
            ["git", "-C", repo_path, "add", "-A"],
            capture_output=True, text=True, check=False,
        )
        return result.returncode == 0
    except FileNotFoundError:
        return False

# Single argv entries above this size risk E2BIG (MAX_ARG_STRLEN).
_MAX_MESSAGE_INLINE = 100 * 1024

def commit(self, repo_path: str, message: str) -> tuple[bool, str]:
    try:
        flags = self.gpg_sign_flag()
        if len(message.encode("utf-8", errors="replace")) > self._MAX_MESSAGE_INLINE:
            import tempfile

            with tempfile.NamedTemporaryFile(
                mode="w", suffix=".commitmsg", prefix="deploynator-", delete=False, encoding="utf-8"
            ) as fh:
                fh.write(message)
                msg_file = fh.name
            try:
                cmd = ["git", "-C", repo_path, "commit"] + flags + ["-F", msg_file]
                result = subprocess.run(cmd, capture_output=True, text=True, check=False)
            finally:
                try:
                    os.unlink(msg_file)
                except OSError:
                    pass
        else:
            cmd = ["git", "-C", repo_path, "commit"] + flags + ["-m", message]
            result = subprocess.run(cmd, capture_output=True, text=True, check=False)
        if result.returncode != 0:
            err_msg = result.stderr.strip() or result.stdout.strip() or "unknown error"
            return False, err_msg
        return True, result.stdout.strip()
    except FileNotFoundError as exc:
        return False, str(exc)

